  const list=targets().filter(t=>t.enabled&&t.canTrack&&(!cameraSearch||t.label.toLowerCase().includes(cameraSearch))),previous=$('viewportTarget').value,signature=JSON.stringify(list.map(t=>[t.id,t.label,t.canBoard]));
